import seaborn as sns
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd


sns.set(style="darkgrid", palette="colorblind")

def violinplot(data_map, title = "Experiment", filename = None):
    labels, data = zip(*data_map.items())

    fig, ax = plt.subplots(figsize=(14, 6))

    #ax.set_xscale("log")

    # Plot data
    ax = sns.violinplot(data=data, inner='box', linewidth=1.2)
    ax.set_xticklabels(labels, fontsize = 16)
    
    # Align colors with Figure 6
    colors = sns.color_palette("colorblind")
    colormap = {
        r'$K = 2$': sns.desaturate(colors[0], 0.75),
        r'$K = 25$': sns.desaturate(colors[1], 0.75),
        r'$K = 50$': sns.desaturate(colors[2], 0.75),
        r'$K = 75$': sns.desaturate(colors[3], 0.75),
        r'$K = 100$': sns.desaturate(colors[4], 0.75),
        r'$K = 150$': sns.desaturate(colors[9], 0.75),
        r'$K = 200$': sns.desaturate(colors[5], 0.75),
        r'$K = 300$': sns.desaturate(colors[6], 0.75),
        r'$K = 400$': sns.desaturate(colors[7], 0.75),
        r'$K = 500$': sns.desaturate(colors[8], 0.75),
              }
    for violin, label in zip(ax.collections,labels):
        violin.set(facecolor=colormap[label])

    # Add line for true treatment effect
    plt.axhline(0.15, color='black', linestyle='--', label=r'True treatment effect $\tau$')

    # Formatting
    plt.yticks(fontsize=18)
    #plt.title(title, fontsize=20)
    plt.ylabel("Estimated treatment effect", fontsize=18)
    plt.legend(fontsize = 18)
    plt.tight_layout()
    if filename:
        plt.savefig(filename)
    plt.show()

